package singbox

import (
	"context"
	"encoding/json"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"testing"
	"time"

	"github.com/google/uuid"
	"github.com/pasarguard/node/common"
	"github.com/pasarguard/node/config"
)

// realityKeypair is generated by `sing-box generate reality-keypair`.
const (
	realityPrivKey = "aDDe6dyBwu2nRFwnalSvl2JcGOU_ajXw1ya-LXoJdEw"
	realityPubKey  = "QaZf-HHDgayd3s1NXHTEFKrKrncahEKZ_R19krM3aFQ"
)

// TestSingBoxVLESSReality runs a VLESS+Reality inbound (the panel's default
// censorship-resistant path) and connects a sing-box client through it, then
// asserts the per-user counter moved.
func TestSingBoxVLESSReality(t *testing.T) {
	exe := singBoxEnvPath(t)
	dir := t.TempDir()
	userID := uuid.New().String()
	const email = "reality-user"

	p := freePorts(t, 5)
	serverPort, apiPort, metricPort, targetPort, socksPort := p[0], p[1], p[2], p[3], p[4]

	startOrigin(t, targetPort)

	serverCfg := fmt.Sprintf(`{
  "log": {"level": "error"},
  "inbounds": [
    {"type":"vless","tag":"vless-reality","listen":"127.0.0.1","listen_port":%d,
     "users":[{"name":%q,"uuid":%q,"flow":"xtls-rprx-vision"}],
     "tls":{"enabled":true,"server_name":"www.microsoft.com","alpn":["h2","http/1.1"],
       "reality":{"enabled":true,
         "handshake":{"server":"www.microsoft.com","server_port":443},
         "private_key":%q,"short_id":["0123456789abcdef"]}}}
  ],
  "outbounds": [{"type":"direct","tag":"direct"}],
  "route": {"final":"direct"}
}`, serverPort, email, userID, realityPrivKey)

	cfg, err := NewConfig(serverCfg, nil)
	if err != nil {
		t.Fatalf("NewConfig: %v", err)
	}
	if err := cfg.ApplyAPI(apiPort); err != nil {
		t.Fatalf("ApplyAPI: %v", err)
	}
	cfg.syncUsers([]*common.User{{
		Email:    email,
		Proxies:  &common.Proxy{Vless: &common.Vless{Id: userID, Flow: "xtls-rprx-vision"}},
		Inbounds: []string{"vless-reality"},
	}})

	nodeCfg := config.NewTestConfig(dir, uuid.New())
	nodeCfg.SingBoxExecutablePath = exe

	ctx, cancel := context.WithTimeout(context.Background(), 120*time.Second)
	defer cancel()

	sb, err := New(ctx, cfg, nil, apiPort, metricPort, nodeCfg)
	if err != nil {
		t.Fatalf("New backend: %v", err)
	}
	defer sb.Shutdown()
	go func() {
		for range sb.Logs() {
		}
	}()

	clientCfg := map[string]any{
		"log":      map[string]any{"level": "debug"},
		"inbounds": []any{map[string]any{"type": "mixed", "tag": "socks", "listen": "127.0.0.1", "listen_port": socksPort}},
		"outbounds": []any{
			map[string]any{
				"type": "vless", "tag": "proxy", "server": "127.0.0.1", "server_port": serverPort,
				"uuid": userID, "flow": "xtls-rprx-vision",
				"tls": map[string]any{
					"enabled": true, "server_name": "www.microsoft.com", "insecure": true,
					"utls":    map[string]any{"enabled": true, "fingerprint": "chrome"},
					"reality": map[string]any{"enabled": true, "public_key": realityPubKey, "short_id": "0123456789abcdef"},
				},
			},
			map[string]any{"type": "direct", "tag": "direct"},
		},
		"route": map[string]any{"final": "proxy"},
	}
	buf, _ := json.Marshal(clientCfg)
	cfgPath := filepath.Join(dir, "client.json")
	if err := os.WriteFile(cfgPath, buf, 0o644); err != nil {
		t.Fatalf("write client config: %v", err)
	}
	if out, err := exec.Command(exe, "check", "-c", cfgPath).CombinedOutput(); err != nil {
		t.Fatalf("client config invalid: %v\n%s", err, out)
	}

	logPath := filepath.Join(dir, "client.log")
	logFile, err := os.Create(logPath)
	if err != nil {
		t.Fatalf("client log: %v", err)
	}
	client := exec.Command(exe, "run", "-c", cfgPath)
	client.Stdout = logFile
	client.Stderr = logFile
	if err := client.Start(); err != nil {
		t.Fatalf("start client: %v", err)
	}
	defer func() {
		_ = client.Process.Kill()
		_, _ = client.Process.Wait()
		_ = logFile.Close()
	}()

	if err := waitForPort(socksPort, 15*time.Second); err != nil {
		t.Fatalf("client socks never came up: %v", err)
	}

	received := func() (n int) {
		defer func() {
			if r := recover(); r != nil {
				t.Logf("tunnel error: %v (client log: %s)", r, readTail(logPath))
			}
		}()
		return socksFetch(t, socksPort, targetPort, 2048)
	}()
	t.Logf("vless-reality: received %d bytes", received)

	deadline := time.Now().Add(20 * time.Second)
	var up, down int64
	for time.Now().Before(deadline) {
		stats, err := sb.GetStats(ctx, &common.StatRequest{Type: common.StatType_UserStat, Name: email, Reset_: true})
		if err != nil {
			t.Fatalf("GetStats: %v", err)
		}
		for _, s := range stats.GetStats() {
			if s.GetName() != email || s.GetLink() != "traffic" {
				continue
			}
			if s.GetType() == "uplink" {
				up += s.GetValue()
			}
			if s.GetType() == "downlink" {
				down += s.GetValue()
			}
		}
		if up > 0 && down > 0 {
			break
		}
		time.Sleep(500 * time.Millisecond)
	}
	if up == 0 && down == 0 {
		t.Fatalf("vless-reality: no per-user traffic counted for %q (client log: %s)", email, readTail(logPath))
	}
	t.Logf("vless-reality: counters uplink=%d downlink=%d", up, down)
}
